PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,google_sub TEXT NOT NULL UNIQUE,email TEXT NOT NULL,avatar TEXT,created_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,authenticated_at INTEGER NOT NULL);
CREATE INDEX sessions_owner ON sessions(owner_id);
CREATE TABLE challenges(token_hash TEXT PRIMARY KEY,nonce TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE lots(owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,id TEXT NOT NULL,name TEXT NOT NULL,name_key TEXT NOT NULL,start_on TEXT,end_exclusive TEXT,capacity INTEGER CHECK(capacity BETWEEN 1 AND 99),capacity_policy TEXT NOT NULL CHECK(capacity_policy IN ('soft','strict')),accent TEXT,sort_order INTEGER NOT NULL CHECK(sort_order>=0),is_archived INTEGER NOT NULL CHECK(is_archived IN(0,1)),ended_prompt_dismissed_for TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),deleted_at TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(owner_id,id),CHECK(start_on IS NULL OR end_exclusive IS NULL OR end_exclusive>start_on),CHECK(id!='general' OR (name='General' AND name_key='general' AND start_on IS NULL AND end_exclusive IS NULL AND capacity IS NULL AND capacity_policy='soft' AND is_archived=0 AND deleted_at IS NULL AND sort_order=0)));
CREATE UNIQUE INDEX lots_name ON lots(owner_id,name_key) WHERE deleted_at IS NULL;
CREATE INDEX lots_owner_order ON lots(owner_id,sort_order,id);
CREATE TABLE ideas(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,lot_id TEXT NOT NULL,original_text TEXT NOT NULL,title TEXT NOT NULL,notes TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('parked','active','archived')),kind TEXT NOT NULL CHECK(kind IN('idea','task')),vehicle_size TEXT NOT NULL CHECK(vehicle_size IN('compact','truck')),revisit_on TEXT,date_precision TEXT,date_label TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,activated_at TEXT,archived_at TEXT,archive_reason TEXT,version INTEGER NOT NULL CHECK(version>0),deleted_at TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY(owner_id,lot_id) REFERENCES lots(owner_id,id));
CREATE INDEX ideas_lot_status ON ideas(owner_id,lot_id,status,deleted_at);
CREATE INDEX ideas_owner_updated ON ideas(owner_id,updated_at,id);
CREATE TABLE changes(seq INTEGER PRIMARY KEY AUTOINCREMENT,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,version INTEGER NOT NULL,operation TEXT NOT NULL,payload TEXT,changed_at INTEGER NOT NULL);
CREATE INDEX changes_owner_seq ON changes(owner_id,seq);
CREATE INDEX changes_expiry ON changes(changed_at);
CREATE TABLE sync_devices(owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,id TEXT NOT NULL,registered_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(owner_id,id));
CREATE TABLE processed_mutations(owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,mutation_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(owner_id,mutation_id));
CREATE INDEX receipts_expiry ON processed_mutations(created_at);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE deletion_jobs(token_hash TEXT PRIMARY KEY,complete INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TRIGGER ideas_capacity_insert BEFORE INSERT ON ideas WHEN NEW.status='parked' AND NEW.deleted_at IS NULL BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM lots WHERE owner_id=NEW.owner_id AND id=NEW.lot_id AND (is_archived=1 OR deleted_at IS NOT NULL)) THEN RAISE(ABORT,'lot_unavailable') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM lots l WHERE l.owner_id=NEW.owner_id AND l.id=NEW.lot_id AND l.capacity_policy='strict' AND l.capacity IS NOT NULL AND (SELECT coalesce(sum(CASE vehicle_size WHEN 'truck' THEN 2 ELSE 1 END),0) FROM ideas WHERE owner_id=NEW.owner_id AND lot_id=NEW.lot_id AND status='parked' AND deleted_at IS NULL)+(CASE NEW.vehicle_size WHEN 'truck' THEN 2 ELSE 1 END)>l.capacity) THEN RAISE(ABORT,'strict_capacity') END;
END;
CREATE TRIGGER ideas_capacity_update BEFORE UPDATE ON ideas WHEN NEW.status='parked' AND NEW.deleted_at IS NULL AND (OLD.status!='parked' OR OLD.deleted_at IS NOT NULL OR OLD.lot_id!=NEW.lot_id OR (OLD.vehicle_size='compact' AND NEW.vehicle_size='truck')) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM lots WHERE owner_id=NEW.owner_id AND id=NEW.lot_id AND (is_archived=1 OR deleted_at IS NOT NULL)) THEN RAISE(ABORT,'lot_unavailable') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM lots l WHERE l.owner_id=NEW.owner_id AND l.id=NEW.lot_id AND l.capacity_policy='strict' AND l.capacity IS NOT NULL AND (SELECT coalesce(sum(CASE vehicle_size WHEN 'truck' THEN 2 ELSE 1 END),0) FROM ideas WHERE owner_id=NEW.owner_id AND lot_id=NEW.lot_id AND status='parked' AND deleted_at IS NULL AND id!=NEW.id)+(CASE NEW.vehicle_size WHEN 'truck' THEN 2 ELSE 1 END)>l.capacity) THEN RAISE(ABORT,'strict_capacity') END;
END;
CREATE TRIGGER lots_insert_change AFTER INSERT ON lots BEGIN INSERT INTO changes(owner_id,entity_type,entity_id,version,operation,payload,changed_at) VALUES(NEW.owner_id,'lot',NEW.id,NEW.version,'upsert',NEW.payload,unixepoch()*1000); END;
CREATE TRIGGER lots_update_change AFTER UPDATE ON lots BEGIN INSERT INTO changes(owner_id,entity_type,entity_id,version,operation,payload,changed_at) VALUES(NEW.owner_id,'lot',NEW.id,NEW.version,CASE WHEN NEW.deleted_at IS NULL THEN 'upsert' ELSE 'delete' END,CASE WHEN NEW.deleted_at IS NULL THEN NEW.payload ELSE NULL END,unixepoch()*1000); END;
CREATE TRIGGER ideas_insert_change AFTER INSERT ON ideas BEGIN INSERT INTO changes(owner_id,entity_type,entity_id,version,operation,payload,changed_at) VALUES(NEW.owner_id,'idea',NEW.id,NEW.version,'upsert',NEW.payload,unixepoch()*1000); END;
CREATE TRIGGER ideas_update_change AFTER UPDATE ON ideas BEGIN INSERT INTO changes(owner_id,entity_type,entity_id,version,operation,payload,changed_at) VALUES(NEW.owner_id,'idea',NEW.id,NEW.version,CASE WHEN NEW.deleted_at IS NULL THEN 'upsert' ELSE 'delete' END,CASE WHEN NEW.deleted_at IS NULL THEN NEW.payload ELSE NULL END,unixepoch()*1000); END;
